#include "giant_module_masks.h"
static int giant_module_index(int n){Giant*b=&ex.giant;if(b->archetype==4&&n==6)return 30+b->form;if(n>=7&&b->form>=2)return 24+b->archetype;if(n>=4&&n<6&&b->form>=1)return 18+b->archetype;return (n==6?2:n>=2&&n<6?1:0)*6+b->archetype;}
static int giant_module_alpha(int n,int x,int y){if(x<0||x>=64||y<0||y>=64)return 0;if(giant_module_index(n)>=18&&(n&1))x=63-x;return (giantModuleMask[giant_module_index(n)][y][x>>5]&(1u<<(x&31)))!=0;}
static int giant_module_at(int n,float px,float py,float cx,float cy,float angle,float w,float h){if(w<=0||h<=0)return 0;float a=angle*.01745329252f,c=cosf(a),s=sinf(a),dx=px-cx,dy=py-cy,lx=dx*c+dy*s,ly=-dx*s+dy*c,u=(lx/w+.5f)*64,v=(ly/h+.5f)*64,rx=player_hull_rx(),ry=player_hull_ry(),bx=(rx*fabsf(c)+ry*fabsf(s))*64/w+1,by=(rx*fabsf(s)+ry*fabsf(c))*64/h+1,exx=(fabsf(c)*w+fabsf(s)*h)/128,eyy=(fabsf(s)*w+fabsf(c)*h)/128;int left=clamp((int)floorf(u-bx),0,63),right=clamp((int)ceilf(u+bx),0,63),top=clamp((int)floorf(v-by),0,63),bottom=clamp((int)ceilf(v+by),0,63);for(int y=top;y<=bottom;y++)for(int x=left;x<=right;x++)if(giant_module_alpha(n,x,y)){float xx=((x+.5f)/64-.5f)*w,yy=((y+.5f)/64-.5f)*h,wx=cx+xx*c-yy*s,wy=cy+xx*s+yy*c,qx=fmaxf(0,fabsf(wx-px)-exx)/rx,qy=fmaxf(0,fabsf(wy-py)-eyy)/ry;if(qx*qx+qy*qy<=1)return 1;}return 0;}
static int giant_module_contact(int n){Giant*b=&ex.giant;GiantPart*p=b->parts+n;float oldW=b->previousPartW[n]>0?b->previousPartW[n]:p->w,oldH=b->previousPartH[n]>0?b->previousPartH[n]:p->h,r=hypotf(fmaxf(oldW,p->w),fmaxf(oldH,p->h))*.5f;if(!giant_box_sweep(b->previousPartX[n]-ex.damagePrevX/(float)Q,b->previousPartY[n]-ex.damagePrevY/(float)Q,p->x-g.px/(float)Q,p->y-player_y/(float)Q,r+player_hull_rx(),r+player_hull_ry()))return 0;float distance=hypotf(p->x-b->previousPartX[n]-(g.px-ex.damagePrevX)/(float)Q,p->y-b->previousPartY[n]-(player_y-ex.damagePrevY)/(float)Q)+absn(p->angle-b->previousPartAngle[n])*.01745329252f*r+fabsf(p->w-oldW)+fabsf(p->h-oldH);int steps=clamp((int)ceilf(distance/3)+1,1,256);for(int i=0;i<=steps;i++){float t=i/(float)steps;if(giant_module_at(n,(ex.damagePrevX+(g.px-ex.damagePrevX)*t)/Q,(ex.damagePrevY+(player_y-ex.damagePrevY)*t)/Q,b->previousPartX[n]+(p->x-b->previousPartX[n])*t,b->previousPartY[n]+(p->y-b->previousPartY[n])*t,b->previousPartAngle[n]+(p->angle-b->previousPartAngle[n])*t,oldW+(p->w-oldW)*t,oldH+(p->h-oldH)*t))return 1;}return 0;}
